import { randomBytes } from 'node:crypto';
import { mkdir, rm } from 'node:fs/promises';
import { homedir, tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import {
  cliFailureState,
  readinessDetail,
  readinessFailure,
  readinessMessage,
} from '@graphgoblin/domain';
import type { HarnessReadinessState, PromptSubmission } from '@graphgoblin/contracts';
import type {
  HarnessEvent,
  HarnessPreflight,
  HarnessPort,
  HarnessResult,
  HarnessSession,
  HarnessStartRequest,
} from '@graphgoblin/engine';
import { subscriptionEnvironment } from './environment.js';
import { ClaudeHarnessError, abortError } from './errors.js';
import {
  claudePolicy,
  policyArgs,
  resolvedClaudeSettings,
  SUPPRESSION_ARGS,
  type ClaudePolicy,
} from './policy.js';
import {
  ClaudeAccumulator,
  JsonLines,
  authCategory,
  validClaudeSessionId,
  installedClaudeVersion,
