  result: ClaudeProcessResult,
  signal: AbortSignal,
  cwd: string,
  probe = false,
): void {
  if (result.terminationUnconfirmed)
    throw new ClaudeHarnessError(
      'HARNESS_TERMINATION_UNCONFIRMED',
      probe
